async function saveGamificationSettings(){const settings=state.gamificationSettings||{};const gt=settings.genius_thresholds||{};const ch=settings.champion_casserole_phases||{};const payload={casserole_thresholds:{small:Number($("#cfgCasSmall").value||3),beautiful:Number($("#cfgCasBeautiful").value||4),industrial:Number($("#cfgCasIndustrial").value||6),nuclear:Number($("#cfgCasNuclear").value||8)},casserole_points:{small:Number($("#cfgPtsSmall").value||1),beautiful:Number($("#cfgPtsBeautiful").value||3),industrial:Number($("#cfgPtsIndustrial").value||5),nuclear:Number($("#cfgPtsNuclear").value||10)},casserole_rules:{zero_small:Number($("#cfgZeroSmall").value||3),zero_beautiful:Number($("#cfgZeroBeautiful").value||5),zero_nuclear:Number($("#cfgZeroNuclear").value||8),full_matchday_severity:$("#cfgZeroFull").value||"industrial"},champion_casserole_phases:{...ch,KNOCKOUT_PLAYOFF:$("#cfgChampionPlayoff").value||"beautiful",ROUND_OF_16:$("#cfgChampionR16").value||"small"},genius_thresholds:{...gt,minimum_predictions:Number($("#cfgGeniusMin").value||5),exact_bonus:Number($("#cfgExactBonus").value||2),max:Number($("#cfgGeniusMax").value||10)},record_thresholds:{precision_evening:Number($("#cfgPrecisionEvening").value||5),precision_period:Number($("#cfgPrecisionPeriod").value||20),precision_season:Number($("#cfgPrecisionSeason").value||30)},record_categories:($("#cfgRecordCategories").value||"").split(',').map(x=>x.trim()).filter(Boolean),secret_retro_notify:$("#cfgSecretRetro").checked};const {error}=await sb.rpc("admin_update_gamification_settings_v070",{p_season_id:state.season.id,p_payload:payload});if(error)return setMsg("#adminGamiMsg",friendlyError(error),"error");await Promise.all([loadGamificationData(),loadAdminGamificationData()]);renderAdminGamification();toast("Configuration Gamification enregistrée.");}
function closurePreviewHTML(data){const poele=data?.poele_winners||[],genius=data?.genius_winners||[];return `<div class="closing-summary"><p>🍳 <b>Poêle d’Or</b><br>${poele.length?poele.map(x=>`${esc(x.username)} — ${Number(x.points||0)} pts · ☢ ${Number(x.nuclear||0)} · ind. ${Number(x.industrial||0)}`).join('<br>'):'Aucun candidat'}</p><p>🧠 <b>Génie de la saison</b><br>${genius.length?genius.map(x=>`${esc(x.username)} — ${Number(x.points||0)} pts`).join('<br>'):'Aucun candidat'}</p><p>🏆 ${Number(data?.records||0)} record(s), dont ${Number(data?.active_records||0)} actif(s).</p></div>`;}
async function previewGamificationClosure(){const {data,error}=await sb.rpc("admin_preview_gamification_close_v070",{p_season_id:state.season.id});if(error)return toast(friendlyError(error),"error");modal("👁 Prévisualisation de clôture",closurePreviewHTML(data));}
async function closeGamificationSeason(){const {data:preview,error:pErr}=await sb.rpc("admin_preview_gamification_close_v070",{p_season_id:state.season.id});if(pErr)return toast(friendlyError(pErr),"error");const root=modal("🏁 Clôturer la gamification",`${closurePreviewHTML(preview)}<div class="warning-box">Après validation, les résultats sont figés jusqu’à une réouverture explicite et auditée.</div><button id="confirmCloseGamiV070" class="btn danger">Confirmer la clôture</button><div id="closeGamiMsg" class="form-msg"></div>`);$("#confirmCloseGamiV070",root).onclick=async()=>{const {data,error}=await sb.rpc("admin_close_gamification_v070",{p_season_id:state.season.id});if(error)return setMsg("#closeGamiMsg",friendlyError(error),"error");$("#modalRoot").innerHTML="";await Promise.all([loadGamificationData(),loadAdminGamificationData()]);renderAdminGamification();modal("🏁 Gamification clôturée",closurePreviewHTML(data));};}
async function reopenGamificationSeason(){const reason=prompt("Motif de réouverture de la gamification :");if(!reason)return;const {error}=await sb.rpc("admin_reopen_gamification_v070",{p_season_id:state.season.id,p_reason:reason});if(error)return toast(friendlyError(error),"error");await Promise.all([loadGamificationData(),loadAdminGamificationData()]);renderAdminGamification();toast("Gamification réouverte.");}
function openGamificationTestNotification(){const root=modal("🔔 Notification Gamification TEST",`<div class="field"><label>Destinataire</label><select id="gamiTestNotifPlayer">${playerSelectOptions(state.user?.id)}</select></div><div class="field"><label>Titre</label><input id="gamiTestNotifTitle" value="🧪 TEST Gamification"></div><div class="field"><label>Message</label><textarea id="gamiTestNotifBody">Le laboratoire du Nid vient de générer une notification TEST.</textarea></div><label class="notification-toggle"><span>Demander un Push immédiat</span><input id="gamiTestNotifPush" type="checkbox" checked></label><button id="sendGamiTestNotifBtn" class="btn gold">Envoyer uniquement à ce joueur</button><div id="gamiTestNotifMsg" class="form-msg"></div>`);$("#sendGamiTestNotifBtn",root).onclick=async()=>{const {error}=await sb.rpc("admin_send_gamification_test_notification_v070",{p_user_id:$("#gamiTestNotifPlayer",root).value,p_season_id:state.season.id,p_title:$("#gamiTestNotifTitle",root).value.trim(),p_body:$("#gamiTestNotifBody",root).value.trim(),p_push:$("#gamiTestNotifPush",root).checked});if(error)return setMsg("#gamiTestNotifMsg",friendlyError(error),"error");setMsg("#gamiTestNotifMsg","Notification TEST envoyée. Aucun envoi global.","ok");};}

function latestFinishedPersonalSummary(){
  const rows=(state.history||[]).filter(x=>x&&x.match_id);if(!rows.length)return null;
  const byDay=new Map();for(const r of rows){const m=(state.allMatches||[]).find(x=>String(x.id)===String(r.match_id));if(m?.is_test||r.match_status!=="finished")continue;const key=String(r.matchday_number??m?.matchday_id??"none");const g=byDay.get(key)||{id:key,latest:0,points:0,matches:0,exacts:0,zeros:0};g.latest=Math.max(g.latest,new Date(r.kickoff_at||m?.kickoff_at||0).getTime());const pts=Number(r.points||0);g.points+=pts;g.matches++;if(Number(r.prediction_home)===Number(r.result_home)&&Number(r.prediction_away)===Number(r.result_away))g.exacts++;if(pts===0)g.zeros++;byDay.set(key,g);}return [...byDay.values()].sort((a,b)=>b.latest-a.latest)[0]||null;
}
function renderHomeNarrativeCard(){const root=$("#homeNarrativeCard");if(!root)return;const s=latestFinishedPersonalSummary();if(!s){root.classList.add("hidden");return;}const mine=(state.standings||state.rankingRows||[]).find(r=>String(r.user_id)===String(state.user?.id))||{};const variation=Number(mine.variation||0),rank=Number(mine.rank||mine.display_rank||0);const avg=s.matches?Number(s.points)/s.matches:0;const key=avg>=4||s.exacts>=2?"summary_good":avg<1.5?"summary_bad":"summary_neutral";const vars={player:state.profile?.username||"",points:s.points,matches:s.matches,exacts:s.exacts,zeros:s.zeros,rank:rank||"—",rank_delta:Math.abs(variation)};const fallback=key==="summary_good"?`${s.points} points et ${s.exacts} exact(s). Belle journée.`:key==="summary_bad"?`${s.points} points. Le Hibou classe cette journée dans le dossier “à oublier”.`:`${s.points} points : une journée correcte, sans déclaration de guerre aux statistiques.`;const text=narrativeTextForEvent(key,s.id,vars,fallback);let rankText="";if(variation!==0){const rk=variation>0?"ranking_up":"ranking_down";rankText=narrativeTextForEvent(rk,`rank:${s.id}:${rank}:${variation}`,vars,variation>0?`Tu gagnes ${variation} place(s) et montes au rang ${rank}.`:`Tu perds ${Math.abs(variation)} place(s) et glisses au rang ${rank}.`);}root.classList.remove("hidden");root.innerHTML=`<span class="eyebrow">🦉 Le Hibou résume</span><p>${esc(text)}</p>${rankText?`<p class="home-narrative-rank">${esc(rankText)}</p>`:''}<small>${s.points} pts · ${s.exacts} exact(s) · ${s.matches} match(s)${rank?` · #${rank}`:''}</small>`;}
function eventCardHTML(e){
  const sev=esc(e.severity||"");
  return `<article class="museum-event ${esc(e.event_type)} ${sev}"><div class="museum-event-icon">${gamificationEventIcon(e)}</div><div><small>${esc(fmtDate(e.created_at))}${e.is_manual?' · Attribuée par le Hibou masqué':''}${e.is_test?' · 🧪 TEST':''}</small><h4>${esc(e.title||(e.event_type==='casserole'?'Casserole':'Coup de génie'))}</h4><p>${esc(e.message||'')}</p>${e.media_url?`<img class="museum-event-media" src="${esc(e.media_url)}" alt="Illustration de la distinction" loading="lazy">`:''}${Array.isArray(e.labels)&&e.labels.length?`<div class="event-labels">${e.labels.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:''}</div><strong>${e.points>0?`+${e.points}`:e.points} ${e.event_type==='casserole'?'🍳':'✨'}</strong></article>`;
}
async function openPlayerMuseum(userId){
  try{
    const p=state.profileDirectory.get(String(userId));const s=await loadPublicMuseum(userId);if(!s)return;
    const badges=(s.badges||[]),obtained=badges.filter(b=>b.obtained),events=s.events||[],records=s.records||[];
    modal(`🏛️ Musée · ${p?.username||'Joueur'}`,`<div class="museum-public-kpis"><span>${obtained.length} badges</span><span>${Number(s.metrics?.records_count||records.length||0)} records</span><span>${Number(s.metrics?.casserole_points||0)} 🍳</span><span>${Number(s.metrics?.genius_points||0)} ✨</span></div><div class="admin-subhead"><div><h4>Badges</h4><p>Les secrets que tu n’as pas découverts toi-même restent masqués.</p></div></div><div class="museum-badge-grid compact">${obtained.slice(0,18).map(badgeCardHTML).join('')||'<div class="empty">Aucun badge public.</div>'}</div><div class="admin-subhead"><div><h4>Records</h4></div></div><div class="record-grid">${records.slice(0,8).map(recordCardHTML).join('')||'<div class="empty">Aucun record.</div>'}</div><div class="admin-subhead"><div><h4>Casseroles & Génie</h4></div></div><div class="museum-event-list">${events.slice(0,12).map(eventCardHTML).join('')||'<div class="empty">Aucune pièce publique.</div>'}</div>`);
  }catch(err){toast(friendlyError(err),"error");}
}
